"""Temporary encoding cross-check (not part of the patch)."""

import pytest
from PyQt5.QtCore import QUrl

from qutebrowser.utils import urlutils


@pytest.fixture(autouse=True)
def init_config(config_stub):
    config_stub.val.url.searchengines = {
        'test': 'http://www.qutebrowser.org/?q={}',
        'DEFAULT': 'http://www.example.com/?q={}',
    }


@pytest.mark.parametrize('open_base_url', [True, False])
@pytest.mark.parametrize('txt, encoded', [
    ('test a&b=c#d', 'http://www.qutebrowser.org/?q=a%26b%3Dc%23d'),
    ('test foo bar', 'http://www.qutebrowser.org/?q=foo%20bar'),
    ('test with/slash-dash', 'http://www.qutebrowser.org/?q=with%2Fslash-dash'),
    ('a+b c', 'http://www.example.com/?q=a%2Bb%20c'),
])
def test_encoding(config_stub, open_base_url, txt, encoded):
    config_stub.val.url.open_base_url = open_base_url
    url = urlutils._get_search_url(txt)
    assert url.toString(QUrl.FullyEncoded) == encoded
EOF
